L1: #!/usr/bin/env node
L2: /**
L3:  * dextestweb · 视频切片 / GIF / 抽帧 / 联络表
L4:  *
L5:  *   node clip.js cut   <video> <start> <duration> <out.mp4> [--width 960] [--crf 23]
L6:  *   node clip.js gif   <video> <start> <duration> <out.gif>  [--width 960] [--fps 8] [--crop 1240:720:180:150]
L7:  *   node clip.js frame <video> <time> <out.png>
L8:  *   node clip.js sheet <video> --times 36,48,60 --out sheet.png [--width 620] [--cols 6]
L9:  *
L10:  * 约定：
L11:  *   - 切点从"动作前 2 秒"开始，结果出现后再留 3~5 秒。
L12:  *   - GIF 走两遍调色板；palettegen 必须 -frames:v 1，否则报 "Could not get frame filename number 2"。
L13:  *   - GIF > 3MB 时用 --crop / 降 --fps / 降 --width，通常 9MB → 500KB。
L14:  */
L15: 
L16: const { execFileSync } = require('child_process');
L17: const fs = require('fs');
L18: const path = require('path');
L19: 
L20: const argv = process.argv.slice(2);
L21: const cmd = argv[0];
L22: const flags = {};
L23: const pos = [];
L24: for (let i = 1; i < argv.length; i++) {
L25:   const a = argv[i];
L26:   if (a.startsWith('--')) flags[a.slice(2)] = argv[i + 1] && !argv[i + 1].startsWith('--') ? argv[++i] : true;
L27:   else pos.push(a);
L28: }
L29: 
L30: const FFMPEG = process.env.FFMPEG || 'ffmpeg';
L31: const run = (args) => execFileSync(FFMPEG, ['-y', '-hide_banner', '-loglevel', 'error', ...args], { stdio: 'inherit' });
L32: const num = (v, d) => (v === undefined ? d : Number(v));
L33: 
L34: function cut(src, start, dur, out) {
L35:   const width = num(flags.width, 0);
L36:   const vf = width ? ['-vf', `scale=${width}:-2:flags=lanczos`] : [];
L37:   run(['-ss', String(start), '-i', src, '-t', String(dur), ...vf,
L38:     '-c:v', 'libx264', '-preset', 'medium', '-crf', String(num(flags.crf, 23)),
L39:     '-pix_fmt', 'yuv420p', '-movflags', '+faststart', '-an', out]);
L40:   console.log('[cut]', out, (fs.statSync(out).size / 1048576).toFixed(2) + 'MB');
L41: }

