L1: #!/usr/bin/env node
L2: /**
L3:  * dextestweb · 报告打包：单文件 HTML + PDF
L4:  *
L5:  *   node pack.js --html report.html [--out dist] [--name 302MOM-问题清单] [--no-pdf] [--gif-to-mp4]
L6:  *
L7:  * 为什么必须做单文件版：
L8:  *   带中文文件名的相对路径，在很多查看器（各类预览面板、邮件客户端、部分看图软件）里解析失败，
L9:  *   用户只会看到"图片打不开"。把图片/视频 base64 内嵌后，一个文件就能转发、双击即看。
L10:  *
L11:  * 做什么：
L12:  *   1. <img src>/<video src> 引用的本地资源 → base64
L13:  *   2. 大 GIF（>2MB）→ 转成循环播放的 mp4（更小、不掉帧，需要 ffmpeg）
L14:  *   3. 注入灯箱（点图放大）+ 打印样式（白底、单列图、隐藏视频）
L15:  *   4. 用 Playwright 的 page.pdf() 生成打印版 PDF
L16:  */
L17: 
L18: const fs = require('fs');
L19: const path = require('path');
L20: const { execFileSync } = require('child_process');
L21: 
L22: const argv = process.argv.slice(2);
L23: const flags = {};
L24: for (let i = 0; i < argv.length; i++) {
L25:   const a = argv[i];
L26:   if (a === '--no-pdf') flags.noPdf = true;
L27:   else if (a === '--gif-to-mp4') flags.gifToMp4 = true;
L28:   else if (a.startsWith('--')) flags[a.slice(2)] = argv[++i];
L29: }
L30: 
L31: if (!flags.html) {
L32:   console.log('用法: node pack.js --html report.html [--out dist] [--name 报告名] [--no-pdf] [--gif-to-mp4]');
L33:   process.exit(1);
L34: }
L35: 
L36: const HTML = path.resolve(flags.html);
L37: const BASE = path.dirname(HTML);
L38: const OUT = path.resolve(flags.out || BASE);
L39: const NAME = flags.name || path.basename(HTML, path.extname(HTML));
L40: const MIME = {
L41:   '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.webp': 'image/webp',
L42:   '.gif': 'image/gif', '.svg': 'image/svg+xml', '.mp4': 'video/mp4', '.webm': 'video/webm'
L43: };
L44: const MB = (f) => fs.statSync(f).size / 1048576;
L45: const dataUri = (f) => `data:${MIME[path.extname(f).toLowerCase()] || 'application/octet-stream'};base64,${fs.readFileSync(f).toString('base64')}`;

